fn reverseWords(sentence: Text) -> Text {
  let words = sentence.split(" ")
  if words.length() == 0 { return "" }
  var result = ""
  var i = words.length() - 1
  while i >= 0 {
    result = result + words[i]
    if i > 0 { result = result + " " }
    i = i - 1
  }
  return result
}

test "reverseWords function" {
  expect reverseWords("hello world") == "world hello"
  expect reverseWords("the quick brown fox") == "fox brown quick the"
  expect reverseWords("") == ""
  expect reverseWords("single") == "single"
}

fn fizzBuzz(n: Number) -> Text {
  if n % 3 == 0 and n % 5 == 0 {
    return "fizzbuzz"
  } else if n % 3 == 0 {
    return "fizz"
  } else if n % 5 == 0 {
    return "buzz"
  }
  return n.to_text()
}

test "fizzBuzz function" {
  expect fizzBuzz(3) == "fizz"
  expect fizzBuzz(5) == "buzz"
  expect fizzBuzz(15) == "fizzbuzz"
  expect fizzBuzz(7) == "7"
  expect fizzBuzz(0) == "fizzbuzz"
}

