fn maxOrZero(list: Number[]) -> Number {
  if list.length() == 0 {
    return 0
  }
  var max = list[0]
  for n in list {
    if n > max {
      max = n
    }
  }
  return max
}

test "the ask's own tests" {
  expect maxOrZero([5, 3, 9, 1]) == 9
  expect maxOrZero([-2, -5, -1]) == -1
  expect maxOrZero([7]) == 7
  expect maxOrZero([3.5, 2.1]) == 3.5
  expect maxOrZero([]) == 0
}

