fn write_file(name: Text, content: Text) -> Bool {
  if name.length() == 0 { return false }
  var all_space = true
  for c in name.chars() {
    if c != " " { all_space = false }
  }
  if all_space { return false }
  return true
}

test "write_file's own tests" {
  expect write_file("index.html", "<html></html>") == true
  expect write_file("style.css", "body {margin:0;}") == true
  expect write_file("", "") == false
  expect write_file("   ", "content") == false
}
